insert into public.stories (slug, title, summary, content, category, author_name, author_role, author_avatar, featured_image, published_date, reading_time, is_featured, is_editors_pick, status) values ('green-rebirth-himalayan-ridges', 'The Green Rebirth of the Himalayan Ridges', 'How community-led seed banks and traditional oak planting are bringing drying water springs back to life across rural Uttarakhand.', 'For decades, the standard narrative from the lower Himalayan ridge of Uttarakhand was one of ecological distress. Rapid deforestation combined with the monoculture of fire-prone pine forests had depleted local water tables, drying up ancient mountain springs (known locally as Naulas).
insert into public.stories (slug, title, summary, content, category, author_name, author_role, author_avatar, featured_image, published_date, reading_time, is_featured, is_editors_pick, status) values ('solar-pixels-rural-classrooms-digital', 'Solar Pixels: Rural Classrooms Go Digital', 'A solar-powered classroom initiative in Bihar is defying power grid limitations and transforming student attendance rates.', 'In the remote villages of northern Bihar, grid electricity is notoriously intermittent. For schools trying to prepare children for a digital future, this meant computer labs stood empty, accumulating dust.
insert into public.stories (slug, title, summary, content, category, author_name, author_role, author_avatar, featured_image, published_date, reading_time, is_featured, is_editors_pick, status) values ('mobile-healing-vans-thar-desert', 'The Mobile Healing Vans of Thar Desert', 'Niramaya Health Coalition is using off-grid mobile clinics to slash maternal mortality rates in desert communities.', 'Living in remote settlements within the Thar Desert means the nearest hospital can be up to 70 kilometers away across sandy, roadless terrain. For pregnant women, this distance has historically resulted in high-risk home deliveries and elevated mortality rates.
insert into public.stories (slug, title, summary, content, category, author_name, author_role, author_avatar, featured_image, published_date, reading_time, is_featured, is_editors_pick, status) values ('weaving-independence-loom-revolution-barmer', 'Weaving Independence: The Loom Revolution of Barmer', 'A micro-finance collective is enabling rural women artisans to break free from local middlemen and sell textiles globally.', 'Barmer''s traditional hand-loomed textiles have always been prized, yet the women weavers who create them rarely saw fair returns, trapped by exploitative networks of local traders.
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 12', 'The Green Standard', 'June', '2026', '2026-06-01', 'https://images.unsplash.com/photo-1542601906990-b4d3fb778b09?auto=format&fit=crop&w=600&q=80', 'In this edition, we turn our spotlight on the innovators rewriting our ecological contract. From community seed bank networks to industrial scale solar transitions, the grass roots are leading the way.', array['The Green Rebirth of the Himalayan Ridges', 'Solar Pixels: Rural Classrooms Go Digital', 'The Mobile Healing Vans of Thar Desert']::text[], false, false, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 11', 'Bridges of Empowerment', 'May', '2026', '2026-05-01', 'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?auto=format&fit=crop&w=600&q=80', 'Empowerment begins with agency. This issue celebrates the women-led cooperatives and educational reforms breaking generational cycle barriers across developing regions.', array['Weaving Independence: The Loom Revolution of Barmer']::text[], true, false, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 10', 'Digital Horizons', 'April', '2026', '2026-04-01', 'https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=600&q=80', 'Exploring how technology and internet access are democratizing education in the most remote corners of the world.', array['Coding in the Desert', 'Satellites for Schools']::text[], false, true, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 9', 'Healing Hands', 'March', '2026', '2026-03-01', 'https://images.unsplash.com/photo-1584515933487-779824d29309?auto=format&fit=crop&w=600&q=80', 'A deep dive into the heroic efforts of mobile medical units and off-grid healthcare workers during the peak of the monsoon floods.', array['The Boat Clinics of Assam', 'Vaccines on Foot']::text[], true, false, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 8', 'Corporate Consciousness', 'February', '2026', '2026-02-01', 'https://images.unsplash.com/photo-1497215728101-856f4ea42174?auto=format&fit=crop&w=600&q=80', 'When profits meet purpose. We investigate the CSR initiatives that are actually moving the needle, rather than just ticking boxes.', array['The New Boardroom Agenda']::text[], false, false, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 7', 'Seeds of Change', 'January', '2026', '2026-01-01', 'https://images.unsplash.com/photo-1592621385612-4d7129426394?auto=format&fit=crop&w=600&q=80', 'Agriculture is the backbone of civilization. In our first issue of the year, we explore indigenous farming techniques returning to the mainstream.', array['Millet: The Miracle Grain']::text[], false, true, 'published');
  insert into public.magazine_issues (issue_number, title, month, year, release_date, cover_image, editors_note, featured_articles, is_trending, is_most_read, status) values ('Vol. 6', 'Urban Resurgence', 'December', '2025', '2025-12-01', 'https://images.unsplash.com/photo-1449844908441-8829872d2607?auto=format&fit=crop&w=600&q=80', 'How grassroots organizers are reclaiming concrete jungles and turning abandoned plots into community food forests.', array['Rooftop Gardens of Mumbai']::text[], false, false, 'published');
  insert into public.interviews (title, interviewee, position, organization, photo, quote, highlights, questions, status) values ('Local Action Beats Global Rhetoric', 'Sunita Devi', 'Founder', 'Himalayan Seed Trust', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=800&q=80', 'We spent decades waiting for climate treaties to solve mountain water problems. The answer was in our native seeds all along.', array['Mobilized 800+ women to create local broadleaf seed nurseries.', 'Recharged 7 ancient mountain springs that had been dry for over a decade.', 'Developed a scalable, community-managed forestry model.']::text[], '[{"q":"What led you to prioritize native oaks over fast-growing pines?","a":"Pine forests are commercial but they do not retain soil moisture and their needles cause massive forest fires. Native broadleaved oaks act like massive sponges; their deep roots hold water and enrich soil ecosystems."},{"q":"How did you convince local villagers to participate?","a":"By linking ecological restoration to direct livelihood and water security. When women do not have to walk 5 kilometers daily for a bucket of water, the incentive to protect the forest becomes permanent."}]'::jsonb, 'published');
  insert into public.testimonials (quote, author, role, organization, sort_order) values ('The Impact Ledger does not just write articles-they provide deep, investigative narratives that give our grassroots efforts national visibility and credibility.', 'Sunita Devi', 'Director', 'Himalayan Seed Trust', 0);
  insert into public.testimonials (quote, author, role, organization, sort_order) values ('As a CSR committee member, this publication is our primary source of inspiration. It shows what is actually working in field implementations.', 'Vikramaditya Shah', 'CSR Chair', 'Apex Industrial Corp', 1);
  insert into public.faqs (question, answer, sort_order) values ('What is The Impact Ledger?', 'The Impact Ledger is a premium magazine dedicated to celebrating impact, innovation, leadership, and social progress. Through compelling stories, insightful features, and thought-provoking content, the magazine highlights individuals, organizations, and initiatives that are creating meaningful change across society.', 0);
  insert into public.faqs (question, answer, sort_order) values ('What is the mission of The Impact Ledger?', 'Our mission is to document, recognize, and amplify stories that inspire positive action. We aim to create a platform where achievements, ideas, and initiatives that contribute to social, economic, and environmental progress receive the visibility they deserve.', 1);
  insert into public.faqs (question, answer, sort_order) values ('Who is The Impact Ledger designed for?', 'The Impact Ledger is designed for business leaders, CSR professionals, NGOs, policymakers, educators, students, entrepreneurs, investors, changemakers, and readers who are passionate about impact, leadership, and sustainable development.', 2);
  insert into public.faqs (question, answer, sort_order) values ('What kind of content does the magazine feature?', 'Each edition features a curated mix of inspiring stories, expert perspectives, leadership insights, social impact features, community success stories, informative articles, engaging reader sections, and selected industry highlights that provide both knowledge and inspiration.', 3);
  insert into public.faqs (question, answer, sort_order) values ('What topics does The Impact Ledger cover?', 'The magazine covers a broad range of subjects including CSR, NGOs, education, healthcare, women empowerment, sustainability, environment, youth development, livelihoods, innovation, government initiatives, legal affairs, sports, entertainment, beauty and wellness, leadership, humanitarian efforts, and community development.', 4);
  insert into public.faqs (question, answer, sort_order) values ('Is The Impact Ledger only focused on CSR and NGOs?', 'No. While CSR and NGO initiatives are central to our publication, we also explore developments in business, governance, public policy, leadership, innovation, culture, and other sectors that contribute to societal growth and transformation.', 5);
  insert into public.faqs (question, answer, sort_order) values ('Can organizations and individuals be featured in the magazine?', 'Yes. We welcome submissions from corporations, NGOs, government institutions, educational organizations, social enterprises, community groups, and individual changemakers whose work demonstrates meaningful impact and excellence.', 6);
  insert into public.faqs (question, answer, sort_order) values ('How can I submit a story or initiative for consideration?', 'Stories, projects, achievements, and impact initiatives can be submitted through our editorial team for review. Selected submissions may be featured in upcoming editions based on relevance, credibility, and impact.', 7);
  insert into public.faqs (question, answer, sort_order) values ('Is The Impact Ledger available in print?', 'Yes. The Impact Ledger is published as a professionally curated magazine and is available through partner networks, and authorized distribution channels.', 8);
  insert into public.faqs (question, answer, sort_order) values ('Does the magazine accept advertisements?', 'Yes. The Impact Ledger collaborates with organizations, brands, institutions, and partners whose values align with innovation, responsibility, sustainability, and positive societal impact.', 9);
  insert into public.faqs (question, answer, sort_order) values ('What is Corporate Social Responsibility (CSR)?', 'Corporate Social Responsibility (CSR) is the commitment of businesses and organizations to contribute positively to society through initiatives that support education, healthcare, environmental sustainability, community welfare, and inclusive growth.', 10);
  insert into public.faqs (question, answer, sort_order) values ('How does The Impact Ledger ensure content quality?', 'Our editorial team carefully reviews all submissions and featured content to maintain high standards of accuracy, relevance, credibility, and editorial excellence.', 11);
  insert into public.faqs (question, answer, sort_order) values ('What makes The Impact Ledger unique?', 'The Impact Ledger combines impactful storytelling, insightful analysis, inspiring achievements, leadership perspectives, and engaging reader experiences into a single publication that informs, inspires, and celebrates progress.', 12);
  insert into public.faqs (question, answer, sort_order) values ('What is the vision of The Impact Ledger?', 'Our vision is to become a trusted and influential publication that connects people, organizations, and ideas while inspiring collective action toward a more inclusive, sustainable, and prosperous future.', 13);
  insert into public.faqs (question, answer, sort_order) values ('How can I stay connected with The Impact Ledger?', 'Readers can stay connected through special editions, partnerships, and our official communication channels for the latest stories, insights, and opportunities.', 14);
